<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class StudentMovementController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$students=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->select('s.*','g.name as group_name');if($r->filled('group'))$students->where('s.current_group_id',$r->integer('group'));if($r->filled('q')){$q='%'.$r->q.'%';$students->where(fn($x)=>$x->where('s.last_name','like',$q)->orWhere('s.first_name','like',$q)->orWhere('s.middle_name','like',$q));}$students=$students->orderBy('s.last_name')->limit(200)->get();$history=DB::table('student_movements as m')->join('students as s','s.id','=','m.student_id')->leftJoin('study_groups as fg','fg.id','=','m.from_group_id')->leftJoin('study_groups as tg','tg.id','=','m.to_group_id')->where('m.academic_period_id',$p->id)->select('m.*','s.last_name','s.first_name','s.middle_name','fg.name as from_group','tg.name as to_group')->orderByDesc('m.effective_on')->orderByDesc('m.id')->limit(100)->get();return view('academic-office.movements',compact('p','groups','students','history'));}
 public function create(Request $r,$student){$this->ok($r);$s=DB::table('students')->find($student);abort_if(!$s,404);$p=$r->attributes->get('academic_period');$orders=DB::table('academic_orders')->where('academic_period_id',$p->id)->orderByDesc('order_date')->orderByDesc('id')->limit(200)->get();return view('academic-office.movement',['s'=>$s,'groups'=>DB::table('study_groups')->where('active',1)->orderBy('name')->get(),'orders'=>$orders]);}
 public function store(Request $r,$student){$this->ok($r);$p=$r->attributes->get('academic_period');$s=DB::table('students')->find($student);abort_if(!$s,404);PeriodGuard::writable($p->id);$d=$r->validate(['type'=>'required|in:enrollment,transfer,academic_leave,return_from_leave,expulsion,graduation,reinstatement','to_group_id'=>'nullable|exists:study_groups,id','effective_on'=>'required|date','academic_order_id'=>'nullable|exists:academic_orders,id','order_number'=>'nullable|string|max:100','order_date'=>'nullable|date','basis'=>'nullable|string|max:5000']);if(in_array($d['type'],['enrollment','transfer','return_from_leave','reinstatement']))abort_unless($d['to_group_id'],422,'Нужно выбрать группу.');if(empty($d['academic_order_id'])){abort_if(empty($d['order_number'])||empty($d['order_date']),422,'Выберите приказ или укажите его номер и дату.');}else{$ord=DB::table('academic_orders')->where('academic_period_id',$p->id)->find($d['academic_order_id']);abort_if(!$ord,422,'Приказ относится к другому учебному периоду.');$d['order_number']=$ord->number;$d['order_date']=$ord->order_date;$d['basis']=$d['basis']??$ord->basis;}DB::transaction(function()use($r,$p,$s,$d){DB::table('student_movements')->insert(array_merge($d,['student_id'=>$s->id,'academic_period_id'=>$p->id,'from_group_id'=>$s->current_group_id,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]));$status=match($d['type']){'academic_leave'=>'academic_leave','expulsion'=>'expelled','graduation'=>'graduated',default=>'active'};$group=in_array($d['type'],['enrollment','transfer','return_from_leave','reinstatement'])?$d['to_group_id']:$s->current_group_id;if($d['type']==='transfer'&&$s->current_group_id!=$group)DB::table('student_group_memberships')->where('student_id',$s->id)->where('status','active')->update(['status'=>'inactive','ends_on'=>$d['effective_on'],'updated_at'=>now()]);DB::table('students')->where('id',$s->id)->update(['current_group_id'=>$group,'status'=>$status,'left_on'=>in_array($status,['expelled','graduated'])?$d['effective_on']:null,'updated_at'=>now()]);if($group&&$status==='active')DB::table('student_group_memberships')->updateOrInsert(['student_id'=>$s->id,'academic_period_id'=>$p->id],['study_group_id'=>$group,'starts_on'=>$d['effective_on'],'ends_on'=>null,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);else DB::table('student_group_memberships')->where('student_id',$s->id)->where('status','active')->update(['status'=>'inactive','ends_on'=>$d['effective_on'],'updated_at'=>now()]);if(empty($d['academic_order_id']))DB::table('academic_orders')->updateOrInsert(['academic_period_id'=>$p->id,'number'=>$d['order_number'],'order_date'=>$d['order_date']],['student_id'=>$s->id,'type'=>$d['type'],'title'=>'Движение контингента: '.$d['type'],'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);});return redirect()->route('student.record',$s->id)->with('success','Движение зарегистрировано.');}
 public function plans(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$q=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('individual_study_plans as ip',function($j)use($p){$j->on('ip.student_id','=','s.id')->where('ip.academic_period_id','=',$p->id)->where('ip.status','=','active');})->where('s.status','active');if($r->filled('group'))$q->where('s.current_group_id',$r->integer('group'));if($r->filled('q')){$term='%'.$r->q.'%';$q->where(fn($x)=>$x->where('s.last_name','like',$term)->orWhere('s.first_name','like',$term)->orWhere('s.middle_name','like',$term));}$students=$q->select('s.id','s.last_name','s.first_name','s.middle_name','g.name as group_name',DB::raw('count(ip.id) as plan_count'),DB::raw('coalesce(sum(ip.planned_hours),0) as plan_hours'))->groupBy('s.id','s.last_name','s.first_name','s.middle_name','g.name')->orderBy('s.last_name')->paginate(50)->withQueryString();return view('academic-office.plans',compact('p','groups','students'));}
 public function planEdit(Request $r,$student){$this->ok($r);$p=$r->attributes->get('academic_period');$s=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('s.id',$student)->select('s.*','g.name as group_name')->first();abort_if(!$s,404);$subjects=DB::table('subjects')->orderBy('name')->get();$plans=DB::table('individual_study_plans as ip')->join('subjects as sub','sub.id','=','ip.subject_id')->where(['ip.academic_period_id'=>$p->id,'ip.student_id'=>$student])->select('ip.*','sub.name as subject_name')->orderBy('sub.name')->get();return view('academic-office.plan',compact('p','s','subjects','plans'));}
 public function plan(Request $r,$student){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['subject_id'=>'required|exists:subjects,id','planned_hours'=>'nullable|integer|min:0|max:9999','control_type'=>'nullable|string|max:100','note'=>'nullable|string|max:5000']);DB::table('individual_study_plans')->updateOrInsert(['academic_period_id'=>$p->id,'student_id'=>$student,'subject_id'=>$d['subject_id']],array_merge($d,['status'=>'active','created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Индивидуальный план обновлён.');}
}